result.storeInstallAppSrc:
function(appinfo, callback) {
            if (!appinfo || typeof (appinfo) != 'object') {
                callback({ret: false, msg:{appId: '', message:'wrong param'}})
                return false
            }
            if(!appinfo?.packageName) {
                const ret = Hisense_installApp(appinfo.appId, appinfo.appName, appinfo.thumbnail, appinfo.iconSmall, appinfo.iconBig, appinfo.appUrl, appinfo.storetype, callback, appinfo.configUrl, appinfo.configUrlDownload, appinfo.mediaId)
                callback({ret: ret, msg:{appId: appinfo?.appId, message: ret? "succeed" : "install failed!"}})
                return ret
            } else {
                // package app
                const param = {
                     pkgName: appinfo?.packageName,
                     version: '',
                     appId: appinfo?.appId
                }
                this.sendPkgmgrRequest('install', param, appinfo, callback)
                return true
            }
        }

result.syncExecuteStr:
function(service, args) {
            if (!args?.api) {
                console.error('wrong parameter, should set api')
                return false
            }
            if (this.httpRequest == null) httpRequest = new XMLHttpRequest()
            const url = 'http://localhost:9009/service/' + service
            console.log('post request to ' + url)
            httpRequest.open('POST', url, false)
            httpRequest.setRequestHeader('identifier', this.getIdentifier())
            httpRequest.send(JSON.stringify(args))
            if (httpRequest.status == 200) {
                if (typeof httpRequest.responseText == 'string') {
                    const ret = JSON.parse(httpRequest.responseText)
                    delete ret.session
                    return ret
                }
                return true
            } else {
                console.error('http request failed:' + httpRequest.status)
                return false
            }
        }
